const body = $json.body ?? $json;
const operation = body.operation;
if (!['chat', 'chat_guard', 'evaluation'].includes(operation)) throw new Error('Unsupported operation');
if (typeof body.system !== 'string' || !body.system.trim()) throw new Error('system is required');
if (typeof body.message !== 'string' || !body.message.trim()) throw new Error('message is required');
const history = Array.isArray(body.history) ? body.history.slice(-10).flatMap(item => {
  if (!item || !['user', 'assistant'].includes(item.role) || typeof item.content !== 'string' || !item.content.trim()) return [];
  return [`${item.role}: ${item.content.trim().slice(0, 4000)}`];
}) : [];
const message = body.message.trim().slice(0, 12000);
const prompt = [...history, `user: ${message}`].join('\n');
const maxTokens = Math.min(Math.max(Math.trunc(Number(body.maxTokens)) || 512, 1), 2048);
return [{ json: {
  operation,
  system: body.system.trim().slice(0, 8000),
  prompt,
  model: typeof body.model === 'string' && body.model.trim() ? body.model.trim() : 'gpt-4o-mini',
  maxTokens,
  temperature: operation === 'chat' ? 0.4 : 0
} }];

const raw = String($json.output ?? $json.text ?? $json.message?.content ?? '').trim();
if (!raw) throw new Error('OpenAI returned no message');
const message = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
return [{ json: { message } }];
